use harbor.signal;

fn render(sig: signal.Signal) -> String {
    match sig {
        Calm => "calm",
        Gale(speed) => "gale:".concat(other: speed.to_text()),
        Fog(density) => "fog:".concat(other: density),
    }
}

pub fn entries() -> String {
    let signals = signal.sequence();
    var rendered: List<String> = [];
    var i = 0;
    while i < signals.len() {
        match signals.get(index: i) {
            Some(sig) => rendered.push(item: render(sig)),
            None => unit,
        };
        i = i + 1;
    }
    rendered.join(sep: ";")
}

