use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let items = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < items.len() {
        match items.get(index: i) {
            Some(frame) => {
                let value = match relay.feed.decode(frame: frame) {
                    Ok(n) => n,
                    Err(_) => 0,
                };
                total = total + value;
            },
            None => unit,
        };
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)
}

